00917 {
00918     ImGuiIO& io = ImGui::GetIO();
00919     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00920     IM_ASSERT(bd != nullptr && "Context or backend not initialized! Did you call ImGui_ImplGlfw_InitForXXX()?");
00921 
00922     // Setup display size (every frame to accommodate for window resizing)
00923     int w, h;
00924     int display_w, display_h;
00925     glfwGetWindowSize(bd->Window, &w, &h);
00926     glfwGetFramebufferSize(bd->Window, &display_w, &display_h);
00927     io.DisplaySize = ImVec2((float)w, (float)h);
00928     if (w > 0 && h > 0)
00929         io.DisplayFramebufferScale = ImVec2((float)display_w / (float)w, (float)display_h / (float)h);
00930     if (bd->WantUpdateMonitors)
00931         ImGui_ImplGlfw_UpdateMonitors();
00932 
00933     // Setup time step
00934     // (Accept glfwGetTime() not returning a monotonically increasing value. Seems to happens on disconnecting peripherals and probably on VMs and Emscripten, see #6491, #6189, #6114, #3644)
00935     double current_time = glfwGetTime();
00936     if (current_time <= bd->Time)
00937         current_time = bd->Time + 0.00001f;
00938     io.DeltaTime = bd->Time > 0.0 ? (float)(current_time - bd->Time) : (float)(1.0f / 60.0f);
00939     bd->Time = current_time;
00940 
00941     ImGui_ImplGlfw_UpdateMouseData();
00942     ImGui_ImplGlfw_UpdateMouseCursor();
00943 
00944     // Update game controllers (if enabled and available)
00945     ImGui_ImplGlfw_UpdateGamepads();
00946 }

